<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Bouncing Ball Physics Playground</title>
  <style>
    :root {
      color-scheme: dark;
      --panel: #111827;
      --panel-2: #0b1220;
      --border: #26344c;
      --text: #e5eefc;
      --muted: #8291aa;
      --accent: #72e5ff;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-width: 760px;
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      overflow: auto;
      color: var(--text);
      background:
        radial-gradient(circle at 50% 0%, #18233a 0, #0a0f1a 42%, #05080e 100%);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .playground {
      width: 720px;
      padding: 18px;
      border: 1px solid #25324a;
      border-radius: 22px;
      background: linear-gradient(145deg, rgba(20, 29, 47, 0.96), rgba(9, 14, 24, 0.96));
      box-shadow:
        0 28px 80px rgba(0, 0, 0, 0.55),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }

    header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 14px;
    }

    h1 {
      margin: 0;
      font-size: 22px;
      letter-spacing: 0.02em;
    }

    .subtitle {
      margin-top: 4px;
      color: var(--muted);
      font-size: 13px;
    }

    #count {
      color: #a8b6cc;
      font-size: 13px;
      white-space: nowrap;
    }

    #sim {
      display: block;
      width: 680px;
      height: 500px;
      cursor: crosshair;
      touch-action: none;
      border: 1px solid #32415c;
      border-radius: 14px;
      background: #070c15;
      box-shadow:
        inset 0 0 35px rgba(0, 0, 0, 0.65),
        0 12px 30px rgba(0, 0, 0, 0.3);
    }

    .controls {
      display: flex;
      gap: 10px;
      margin-top: 14px;
    }

    button {
      min-width: 112px;
      padding: 10px 16px;
      border: 1px solid #31405b;
      border-radius: 10px;
      color: #dce8fa;
      background: linear-gradient(#1d2a40, #131d2f);
      font: 600 14px/1 system-ui, sans-serif;
      cursor: pointer;
      box-shadow:
        0 4px 10px rgba(0, 0, 0, 0.25),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
      transition: transform 100ms ease, border-color 100ms ease, filter 100ms ease;
    }

    button:hover {
      border-color: #567196;
      filter: brightness(1.12);
    }

    button:active {
      transform: translateY(1px) scale(0.98);
    }

    #drop {
      color: #041119;
      border-color: #65d6ef;
      background: linear-gradient(#91edff, #4dc9e6);
    }

    #clear {
      margin-left: auto;
      color: #ffccd5;
      border-color: #563245;
      background: linear-gradient(#34202c, #241722);
    }
  </style>
</head>
<body>
  <main class="playground">
    <header>
      <div>
        <h1>Bouncing Ball Playground</h1>
        <div class="subtitle">Click anywhere in the arena to add a ball.</div>
      </div>
      <div id="count">0 balls · paused</div>
    </header>

    <canvas id="sim" width="680" height="500" aria-label="Bouncing ball simulation"></canvas>

    <div class="controls">
      <button id="drop" type="button">Drop a ball</button>
      <button id="play" type="button">Play</button>
      <button id="clear" type="button">Clear</button>
    </div>
  </main>

  <script>
    (() => {
      "use strict";

      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const dropButton = document.getElementById("drop");
      const playButton = document.getElementById("play");
      const clearButton = document.getElementById("clear");
      const countLabel = document.getElementById("count");

      const width = canvas.width;
      const height = canvas.height;
      const gravity = 0.48;
      const restitution = 0.82;
      const state = [];

      let running = false;
      let lastFrame = 0;
      let nextHue = 185;

      function updateStatus() {
        const noun = state.length === 1 ? "ball" : "balls";
        countLabel.textContent =
          `${state.length} ${noun} · ${running ? "playing" : "paused"}`;
        playButton.textContent = running ? "Pause" : "Play";
      }

      function normalizeRadius(r) {
        const value = Number.isFinite(Number(r)) ? Number(r) : 14 + Math.random() * 10;
        return Math.max(4, Math.min(value, Math.min(width, height) / 2));
      }

      function addBall(x, y, vx = 0, vy = 0, r) {
        const radius = normalizeRadius(r);
        const ball = {
          x: Math.max(radius, Math.min(width - radius, Number(x) || 0)),
          y: Math.max(radius, Math.min(height - radius, Number(y) || 0)),
          vx: Number.isFinite(Number(vx)) ? Number(vx) : 0,
          vy: Number.isFinite(Number(vy)) ? Number(vy) : 0,
          r: radius,
          hue: nextHue
        };

        nextHue = (nextHue + 47) % 360;
        state.push(ball);
        draw();
        updateStatus();
        return ball;
      }

      function clearBalls() {
        state.length = 0;
        draw();
        updateStatus();
      }

      function advanceBall(ball, dt) {
        ball.vy += gravity * dt;
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        if (ball.x - ball.r < 0) {
          ball.x = ball.r;
          ball.vx = Math.abs(ball.vx) * restitution;
        } else if (ball.x + ball.r > width) {
          ball.x = width - ball.r;
          ball.vx = -Math.abs(ball.vx) * restitution;
        }

        if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          ball.vy = Math.abs(ball.vy) * restitution;
        } else if (ball.y + ball.r > height) {
          ball.y = height - ball.r;
          ball.vy = -Math.abs(ball.vy) * restitution;

          if (Math.abs(ball.vy) < 0.08) {
            ball.vy = 0;
          }
        }
      }

      function step(dt = 1) {
        dt = Number(dt);
        if (!Number.isFinite(dt) || dt < 0) dt = 1;

        // Substeps keep fast balls stable while edge clamping guarantees
        // that no ball can ever finish a step outside the canvas.
        const subdivisions = Math.max(1, Math.ceil(dt));
        const subDt = dt / subdivisions;

        for (let i = 0; i < subdivisions; i++) {
          for (const ball of state) {
            advanceBall(ball, subDt);
          }
        }

        draw();
        return state;
      }

      function drawBackground() {
        const background = ctx.createLinearGradient(0, 0, 0, height);
        background.addColorStop(0, "#0b1322");
        background.addColorStop(1, "#050912");
        ctx.fillStyle = background;
        ctx.fillRect(0, 0, width, height);

        ctx.save();
        ctx.strokeStyle = "rgba(112, 145, 190, 0.075)";
        ctx.lineWidth = 1;

        for (let x = 20.5; x < width; x += 40) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
          ctx.stroke();
        }

        for (let y = 20.5; y < height; y += 40) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();
        }

        const floorGlow = ctx.createLinearGradient(0, height - 80, 0, height);
        floorGlow.addColorStop(0, "rgba(55, 180, 220, 0)");
        floorGlow.addColorStop(1, "rgba(55, 180, 220, 0.10)");
        ctx.fillStyle = floorGlow;
        ctx.fillRect(0, height - 80, width, 80);
        ctx.restore();
      }

      function drawBall(ball) {
        ctx.save();

        ctx.shadowColor = `hsla(${ball.hue}, 90%, 60%, 0.45)`;
        ctx.shadowBlur = 18;

        const gradient = ctx.createRadialGradient(
          ball.x - ball.r * 0.35,
          ball.y - ball.r * 0.4,
          ball.r * 0.08,
          ball.x,
          ball.y,
          ball.r
        );

        gradient.addColorStop(0, `hsl(${ball.hue}, 95%, 88%)`);
        gradient.addColorStop(0.3, `hsl(${ball.hue}, 86%, 65%)`);
        gradient.addColorStop(1, `hsl(${ball.hue}, 78%, 35%)`);

        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();

        ctx.shadowBlur = 0;
        ctx.strokeStyle = `hsla(${ball.hue}, 100%, 90%, 0.7)`;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        ctx.restore();
      }

      function draw() {
        drawBackground();

        for (const ball of state) {
          drawBall(ball);
        }

        if (state.length === 0) {
          ctx.save();
          ctx.textAlign = "center";
          ctx.fillStyle = "rgba(180, 199, 226, 0.58)";
          ctx.font = "600 17px system-ui, sans-serif";
          ctx.fillText("Click to create a ball", width / 2, height / 2 - 6);
          ctx.fillStyle = "rgba(143, 160, 185, 0.42)";
          ctx.font = "13px system-ui, sans-serif";
          ctx.fillText("Then press Play and watch gravity take over", width / 2, height / 2 + 20);
          ctx.restore();
        }
      }

      function animationFrame(timestamp) {
        if (!running) return;

        if (!lastFrame) lastFrame = timestamp;
        const frameUnits = Math.min(2.5, Math.max(0.1, (timestamp - lastFrame) / (1000 / 60)));
        lastFrame = timestamp;

        step(frameUnits);
        requestAnimationFrame(animationFrame);
      }

      function togglePlay() {
        running = !running;
        lastFrame = 0;
        updateStatus();

        if (running) {
          requestAnimationFrame(animationFrame);
        }
      }

      canvas.addEventListener("pointerdown", event => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) * width / rect.width;
        const y = (event.clientY - rect.top) * height / rect.height;
        addBall(x, y, (Math.random() - 0.5) * 5, -1.5 - Math.random() * 3);
      });

      dropButton.addEventListener("click", () => {
        const r = 14 + Math.random() * 10;
        addBall(
          width * (0.35 + Math.random() * 0.3),
          r + 12,
          (Math.random() - 0.5) * 7,
          Math.random() * 1.5,
          r
        );
      });

      playButton.addEventListener("click", togglePlay);
      clearButton.addEventListener("click", clearBalls);

      window.sim = {
        w: width,
        h: height,
        balls() {
          return state.map(({ x, y, vx, vy, r }) => ({ x, y, vx, vy, r }));
        },
        addBall,
        clear: clearBalls,
        step
      };

      draw();
      updateStatus();
    })();
  </script>
</body>
</html>
